import {GRADES,SLOTS,MATERIALS,itemStats,gearRecipe,amount,canMaterials,equipmentStats,petStats} from './economy.mjs?v=0.4';
import {stats,CLASSES} from './engine.mjs?v=0.4';
import {REGIONS,regionUnlocked} from './regions.mjs?v=0.4';
import {itemIcon} from './avatar.mjs?v=0.4';
import {score,itemScore,compareItem,bestEquipment,filterEquipment,enhancementPlan,ascensionRecipe,salvageRecipe,sourceMode} from './equipment-system.mjs?v=0.4';
const labels={hp:'Sinh lực',mp:'Linh lực',atk:'Công',def:'Thủ'},tiers=['','I','II','III','IV'];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const name=it=>`${SLOTS[it.slot].name} · ${tiers[it.tier]} +${it.enhance}`;
const numbers=v=>Object.entries(labels).map(([k,label])=>`<span>${label} <b>${v[k]||0}</b></span>`).join('');
const badge=it=>`<span class="grade-tag rarity-${it.grade}">${GRADES[it.grade].color} · ${GRADES[it.grade].name}</span>`;
const tabs={craft:'Chế tạo',enhance:'Cường hóa',merge:'Ghép bậc',ascend:'Thăng phẩm'};
const view={grade:'all',status:'all',order:'power',page:0,target:8,quantity:1,tab:'craft'};
export function characterSummary(s){const total=stats(s),gear=equipmentStats(s),pet=petStats(s);return `<div class="character-power"><span>LỰC CHIẾN <strong>${score(total).toLocaleString('vi-VN')}</strong></span><div>${numbers(total)}</div></div><details class="stat-breakdown"><summary>Chi tiết nguồn chỉ số</summary><table class="craft-table"><tr><th>Nguồn</th>${Object.values(labels).map(n=>`<th>${n}</th>`).join('')}</tr>${[['Nhân vật & tu luyện',Object.fromEntries(Object.keys(labels).map(k=>[k,total[k]-gear[k]-pet[k]]))],['Trang bị',gear],['Pet đang chọn',pet],['Tổng cộng',total]].map(([n,v])=>`<tr><td>${n}</td>${Object.keys(labels).map(k=>`<td>${v[k]}</td>`).join('')}</tr>`).join('')}</table><p>Lực chiến Long Mạch = HP + 2×MP + 10×Công + 15×Thủ. Điểm tham khảo; từng chỉ số vẫn quyết định lối chơi.</p></details>`;}
export function renderEquipment(which,c,ui){if(!['inventory','forge'].includes(which))return false;const {game,showPanel,openModal,closeModal,save,hud}=c,s=game.s,$=q=>document.querySelector(q),$$=q=>[...document.querySelectorAll(q)],bag=which==='inventory';
 const refresh=()=>{hud();save();showPanel(which);};
 const navigate=(dest,id)=>{if(id)ui.selected=id;showPanel(dest);};
 const recipe=(r,g)=>`<div class="recipe-list">${Object.entries(r).map(([k,n])=>`<div class="rarity-${g}"><span>${itemIcon(k,g)} ${MATERIALS[k].name}</span><b class="${amount(s,k,g)>=n?'enough':'missing'}">${amount(s,k,g)} / ${n}</b><small>Thiếu ${Math.max(0,n-amount(s,k,g))} · Khóa ${s.materials[k][g].bound} · Giao dịch ${s.materials[k][g].trade}</small><button data-source="${k}" data-source-grade="${g}">Nguồn nguyên liệu</button></div>`).join('')}</div>`;
 const all=filterEquipment(s,{slot:ui.filter,grade:view.grade,status:view.status,order:view.order});view.page=Math.min(view.page,Math.max(0,Math.ceil(all.length/24)-1));
 const selected=s.items.find(i=>i.id===ui.selected);
 const options=(obj,current)=>Object.entries(obj).map(([k,n])=>`<option value="${k}" ${String(current)===k?'selected':''}>${n}</option>`).join('');
 const inventory=`<div class="inventory-heading"><h3>Túi trang bị <small>${s.items.length}/500</small></h3><button id="bestGear" ${!bestEquipment(s).length?'disabled':''}>Mặc tốt nhất · Xem trước</button></div><div class="inventory-filters"><label>Loại<select id="eqSlot">${options({all:'Tất cả',...Object.fromEntries(Object.entries(SLOTS).map(([k,v])=>[k,v.name]))},ui.filter)}</select></label><label>Phẩm chất<select id="eqGrade">${options({all:'Tất cả',...Object.fromEntries(GRADES.map((g,i)=>[i,g.color]))},view.grade)}</select></label><label>Trạng thái<select id="eqStatus">${options({all:'Tất cả',equipped:'Đang mặc',spare:'Chưa mặc',protected:'Bảo vệ',trade:'Giao dịch',bound:'Khóa giao dịch'},view.status)}</select></label><label>Sắp xếp<select id="eqOrder">${options({power:'Lực chiến giảm dần',newest:'Mới nhận'},view.order)}</select></label></div><div class="inventory-grid">${all.slice(view.page*24,(view.page+1)*24).map(it=>`<button class="inventory-tile rarity-${it.grade} ${it.id===ui.selected?'selected':''}" data-pick="${it.id}" aria-label="${name(it)}, ${GRADES[it.grade].color}, ${it.id}"><b class="tile-enhance">+${it.enhance}</b>${itemIcon(it.slot,it.grade)}<strong>${SLOTS[it.slot].name}</strong><small>Bậc ${tiers[it.tier]} · LC ${itemScore(it)}</small><span class="tile-flags">${s.equipped[it.slot]===it.id?'Đang mặc':it.protected?'Bảo vệ':it.tradable?'Giao dịch':'Khóa'}</span></button>`).join('')||'<p class="empty-state">Không có đồ phù hợp bộ lọc. Hãy đổi bộ lọc hoặc chế món đầu tiên.</p>'}</div><div class="inventory-pagination"><button id="eqPrev" ${view.page===0?'disabled':''}>←</button><span>${all.length} món · Trang ${view.page+1}/${Math.max(1,Math.ceil(all.length/24))}</span><button id="eqNext" ${(view.page+1)*24>=all.length?'disabled':''}>→</button></div>`;
 const compare=it=>{const cmp=compareItem(s,it),after=itemStats(it),before=cmp.worn?itemStats(cmp.worn):{};return `<h4>So với ${cmp.worn?name(cmp.worn):'ô đang trống'}</h4><table class="craft-table"><tr><th>Chỉ số</th><th>Đang mặc</th><th>Món chọn</th><th>Thay đổi</th></tr>${Object.entries(labels).map(([k,n])=>`<tr><td>${n}</td><td>${before[k]||0}</td><td>${after[k]}</td><td class="${cmp.delta[k]<0?'missing':'enough'}">${cmp.delta[k]>0?'+':''}${cmp.delta[k]}</td></tr>`).join('')}</table><p>Lực chiến: <b class="${cmp.score<0?'missing':'enough'}">${cmp.score>0?'+':''}${cmp.score}</b></p>`;};
 const detail=selected?`<div class="selected-gear rarity-${selected.grade}"><div class="item-detail-head">${itemIcon(selected.slot,selected.grade)}<div><h3>${name(selected)}</h3>${badge(selected)}<p>${selected.id} · ${selected.tradable?'Có thể giao dịch':'Khóa giao dịch'}${selected.protected?' · Được bảo vệ':''}</p></div></div>${compare(selected)}<div class="toolbar"><button id="eqWear">${s.equipped[selected.slot]===selected.id?'Tháo trang bị':'Mặc món này'}</button><button id="eqProtect">${selected.protected?'Bỏ bảo vệ':'Bảo vệ'}</button><button id="eqPreview">Thử ngoại hình</button></div><p class="subtext">Khóa giao dịch khác với bảo vệ: bảo vệ chặn phân giải, ghép, thăng phẩm và cường hóa.</p>${bag?`<div class="toolbar"><button data-work="enhance">Cường hóa</button><button data-work="merge">Ghép bậc</button><button data-work="ascend">Thăng phẩm</button><button id="eqSalvage" ${!game.eligibleIngredient(selected)?'disabled':''}>Phân giải · Xem trước</button></div>`:''}</div>`:'<div class="empty-state">Chọn một món trong túi để xem chỉ số, so sánh và thao tác.</div>';
 let body;
 if(bag)body=`${characterSummary(s)}<div class="inventory-layout"><section>${inventory}<div class="toolbar"><button data-nav="materials">Kho nguyên liệu</button><button data-nav="forge">Chế tạo mới</button><button data-nav="saves">Xuất / nhập lưu</button></div></section><section>${detail}</section></div>`;
 else{
  let work='';
  if(view.tab==='craft'){
   const r=gearRecipe(ui.slot,ui.grade),materials=Object.fromEntries(Object.entries(r.materials).map(([k,n])=>[k,n*view.quantity])),preview={slot:ui.slot,grade:ui.grade,tier:1,enhance:0};
   work=`<div class="work-intro">Chế món mới từ nguyên liệu cùng màu. Mỗi món bắt đầu bậc I +0, thành công 100%, giao dịch 20%.</div><div class="form-row"><label>Loại đồ<select id="workSlot">${options(Object.fromEntries(Object.entries(SLOTS).map(([k,v])=>[k,v.name])),ui.slot)}</select></label><label>Màu<select id="workGrade">${options(Object.fromEntries(GRADES.map((g,i)=>[i,g.color])),ui.grade)}</select></label><label>Số lượng<select id="workQuantity">${options({1:'1 món',2:'2 món',4:'4 món',8:'8 món',20:'20 món'},view.quantity)}</select></label></div><div class="gear-preview rarity-${ui.grade}">${itemIcon(ui.slot,ui.grade)}<h3>${SLOTS[ui.slot].name} · Bậc I +0</h3><p>${numbers(itemStats(preview))}</p></div>${recipe(materials,ui.grade)}<p>Tổng: <b>${r.gold*view.quantity} đồng</b> / đang có ${s.gold} · ${view.quantity} ô túi</p><button class="primary" id="batchCraft" ${s.items.length+view.quantity>500||s.gold<r.gold*view.quantity||!canMaterials(s,materials,ui.grade)?'disabled':''}>Chế ${view.quantity} ${SLOTS[ui.slot].name}</button><p>Ưu tiên ${s.materialPreference==='bound-first'?'nguyên liệu khóa':'nguyên liệu giao dịch'}. <button data-nav="materials">Đổi ưu tiên / ghép nguyên liệu</button></p>${compare(preview)}`;
  }else if(!selected)work='<p class="empty-state">Chọn món trong túi bên cạnh trước khi nâng cấp.</p>';
  else if(view.tab==='enhance'){
   view.target=Math.max(selected.enhance+1,Math.min(8,view.target));const p=enhancementPlan(selected,view.target);
   work=`${detail}<h3>Cường hóa đến mức đích</h3><p>Thành công 100% · Không phá hủy · Giữ nhãn giao dịch. Quy tắc an toàn của Long Mạch.</p>${p?`<label class="select-line">Mức đích<select id="enhanceTarget">${options(Object.fromEntries(Array.from({length:8-selected.enhance},(_,i)=>[i+selected.enhance+1,'+'+(i+selected.enhance+1)])),view.target)}</select></label><div class="stat-transition"><div>Hiện tại +${selected.enhance}<p>${numbers(p.before)}</p></div><span>→</span><div>Sau nâng +${p.target}<p>${numbers(p.after)}</p></div></div>${recipe(p.materials,selected.grade)}<p>${p.steps} cấp · Tổng ${p.gold} đồng / đang có ${s.gold}</p><button id="enhanceAll" class="primary" ${selected.protected||s.gold<p.gold||!canMaterials(s,p.materials,selected.grade)?'disabled':''}>Xem trước nâng đến +${p.target}</button>${selected.protected?'<p class="missing">Món đang được bảo vệ. Bỏ bảo vệ nếu muốn cường hóa.</p>':''}`:'<p>Đã đạt +8. Nếu đủ bậc IV, chuyển sang Thăng phẩm.</p>'}`;
  }else if(view.tab==='merge'){
   const partners=s.items.filter(i=>game.canMergeItems(selected.id,i.id));work=`${detail}<h3>Ghép hai món → bậc ${tiers[Math.min(4,selected.tier+1)]}</h3><p>Hai món cùng ô, màu, bậc I–III và +0. Món đang mặc hoặc bảo vệ không thể làm phôi. Kết quả +0, giao dịch 20%.</p><label class="select-line">Món thứ hai<select id="workPartner"><option value="">Chọn món</option>${partners.map(i=>`<option value="${i.id}">${name(i)} · ${i.id} · ${i.tradable?'Giao dịch':'Khóa'}</option>`).join('')}</select></label><button id="workMerge" ${!partners.length?'disabled':''}>Xem trước ghép</button>${!partners.length?'<p class="missing">Chưa có cặp hợp lệ. Kiểm tra màu, bậc, +0 và trạng thái mặc/bảo vệ.</p>':''}`;
  }else{
   const r=ascensionRecipe(selected);work=`${detail}<h3>Thăng phẩm</h3>${r?`<p>Tiêu hao ${name(selected)} khi đạt IV +8. Phôi thay <b>${r.saved} ${MATERIALS[r.replaced].name} ${GRADES[selected.grade+1].color}</b> trong công thức mới.</p><div class="gear-preview rarity-${selected.grade+1}">${itemIcon(selected.slot,selected.grade+1)}<h4>Nhận ${SLOTS[selected.slot].name} ${GRADES[selected.grade+1].color} · I +0</h4><p>${numbers(itemStats({...selected,grade:selected.grade+1,tier:1,enhance:0}))}</p></div>${recipe(r.materials,selected.grade+1)}<p>${r.gold} đồng · Thành công 100% · Giao dịch 20%</p><button id="workAscend" ${!game.canAscendItem(selected.id)?'disabled':''}>Xem trước tiêu hao phôi</button>${!game.canAscendItem(selected.id)?'<p class="missing">Cần IV +8, tháo mặc, bỏ bảo vệ và đủ nguyên liệu/đồng.</p>':''}`:'<p>Vàng là phẩm chất cao nhất hiện có.</p>'}`;
  }
  body=`<div class="work-tabs">${Object.entries(tabs).map(([k,n])=>`<button data-work="${k}" class="${view.tab===k?'active':''}">${n}</button>`).join('')}</div><div class="work-layout"><section>${work}</section><section>${inventory}</section></div>`;
 }
 openModal(`<span class="eyebrow">LONG MẠCH · ${esc(s.name)} · ${CLASSES[s.class].name}</span><h2 class="modal-title">${bag?'Túi đồ':'Lò rèn · '+tabs[view.tab]}</h2><div class="panel-tabs">${Object.entries({loadout:'Nhân vật',inventory:'Túi đồ',forge:'Lò rèn',materials:'Nguyên liệu',equipment:'Chế thuốc / tu luyện',codex:'Hướng dẫn',saves:'Xuất / nhập lưu'}).map(([k,n])=>`<button data-nav="${k}" class="${which===k?'active':''}">${n}</button>`).join('')}</div>${body}`,which);
 $$('[data-nav]').forEach(b=>b.onclick=()=>{if(b.dataset.nav==='forge')view.tab='craft';showPanel(b.dataset.nav);});$$('[data-work]').forEach(b=>b.onclick=()=>{view.tab=b.dataset.work;showPanel('forge');});
 for(const[id,key]of [['eqGrade','grade'],['eqStatus','status'],['eqOrder','order']])$('#'+id).onchange=e=>{view[key]=e.target.value;view.page=0;refresh();};$('#eqSlot').onchange=e=>{ui.filter=e.target.value;view.page=0;refresh();};$('#eqPrev').onclick=()=>{view.page--;refresh();};$('#eqNext').onclick=()=>{view.page++;refresh();};
 $$('[data-pick]').forEach(b=>b.onclick=()=>{ui.selected=b.dataset.pick;refresh();});
 const confirm=(title,body,fn)=>{openModal(`<span class="eyebrow">KIỂM TRA TRƯỚC KHI THỰC HIỆN</span><h2>${title}</h2>${body}<div class="toolbar"><button id="confirmEquipment" class="primary">Xác nhận</button><button id="cancelEquipment">Quay lại</button></div>`,'equipment-confirm');$('#confirmEquipment').onclick=()=>{fn();refresh();};$('#cancelEquipment').onclick=()=>showPanel(which);};
 $('#bestGear').onclick=()=>{const best=bestEquipment(s);confirm('Mặc đồ tốt hơn',`<p>Đổi ${best.length} ô. Các món tháo ra vẫn giữ trong túi. Dùng lực chiến tổng hợp, không tự thay khi bằng điểm.</p><ul>${best.map(it=>`<li>${name(it)} · ${GRADES[it.grade].color} · LC +${compareItem(s,it).score}</li>`).join('')}</ul>`,()=>game.equipBest());};
 $('#eqWear')?.addEventListener('click',()=>{if(s.equipped[selected.slot]===selected.id)game.unequip(selected.slot);else game.equip(selected.id);refresh();});$('#eqProtect')?.addEventListener('click',()=>{game.protectItem(selected.id);refresh();});
 $('#eqPreview')?.addEventListener('click',()=>{openModal(`<h2>Thử ${name(selected)}</h2><p>Chỉ xem ngoại hình; chưa thay trang bị đang mặc.</p><section class="avatar-stage"><canvas id="avatarCanvas" aria-label="Xem thử trang bị trên nhân vật"></canvas><div class="avatar-controls"><button id="avatarLeft">↶</button><span>Kéo để xoay</span><button id="avatarRight">↷</button></div></section><button id="returnPreview">Quay lại</button>`,'try-on',{...s,equipped:{...s.equipped,[selected.slot]:selected.id}});$('#returnPreview').onclick=()=>showPanel(which);});
 $('#eqSalvage')?.addEventListener('click',()=>{const id=selected.id,r=salvageRecipe(selected);confirm('Phân giải '+name(selected),`<p>Tiêu hao vĩnh viễn ${id}. Nhận nguyên liệu <b>khóa</b> cùng màu:</p><ul>${Object.entries(r).map(([k,n])=>`<li>${n} ${MATERIALS[k].name} ${GRADES[selected.grade].color}</li>`).join('')}</ul><p>Hoàn 50% công thức gốc × số phôi bậc I, làm tròn xuống. Không hoàn đồng/đá cường hóa.</p>`,()=>{game.salvage(id);ui.selected=null;});});
 $('#workSlot')?.addEventListener('change',e=>{ui.slot=e.target.value;refresh();});$('#workGrade')?.addEventListener('change',e=>{ui.grade=+e.target.value;refresh();});$('#workQuantity')?.addEventListener('change',e=>{view.quantity=+e.target.value;refresh();});$('#batchCraft')?.addEventListener('click',()=>{const out=game.craftBatch(ui.slot,ui.grade,view.quantity);if(out){ui.selected=out.at(-1).id;ui.filter='all';view.grade='all';view.status='all';view.order='newest';view.page=0;}refresh();});
 $('#enhanceTarget')?.addEventListener('change',e=>{view.target=+e.target.value;refresh();});$('#enhanceAll')?.addEventListener('click',()=>{const id=selected.id,p=enhancementPlan(selected,view.target);confirm('Cường hóa đến +'+p.target,`<p>${name(selected)} · ${id}</p><p>Tiêu hao <b>${p.gold} đồng + ${p.materials.stone} đá ${GRADES[p.grade].color}</b> cho ${p.steps} cấp. Thành công 100%, không phá hủy.</p>`,()=>game.enhanceTo(id,p.target));});
 $('#workMerge')?.addEventListener('click',()=>{const a=selected.id,b=$('#workPartner').value;if(!game.canMergeItems(a,b)){game.say('Chọn món thứ hai hợp lệ.');return;}confirm('Ghép lên bậc '+tiers[selected.tier+1],`<p>Tiêu hao ${a} và ${b}: hai ${name(selected)} ${GRADES[selected.grade].color}.</p><p>Nhận một món cùng màu bậc ${tiers[selected.tier+1]} +0. Thành công 100%, giao dịch 20%.</p>`,()=>{const out=game.mergeItems(a,b);if(out)ui.selected=out.id;});});
 $('#workAscend')?.addEventListener('click',()=>{const id=selected.id,r=ascensionRecipe(selected);confirm('Thăng phẩm '+GRADES[selected.grade+1].color,`<p>Tiêu hao ${id} · ${name(selected)} và ${r.gold} đồng.</p><ul>${Object.entries(r.materials).map(([k,n])=>`<li>${n} ${MATERIALS[k].name} ${GRADES[selected.grade+1].color}</li>`).join('')}</ul><p>Phôi thay ${r.saved} ${MATERIALS[r.replaced].name}. Kết quả bậc I +0; có thể giảm chỉ số so với phôi IV +8, hãy xem trước ở bảng thăng phẩm.</p>`,()=>{const out=game.ascendItem(id);if(out)ui.selected=out.id;});});
 $$('[data-source]').forEach(b=>b.onclick=()=>{const k=b.dataset.source,g=+b.dataset.sourceGrade,r=REGIONS[g],unlocked=regionUnlocked(s,g),here=s.map===r.id,mode=sourceMode(k);openModal(`<h2>${MATERIALS[k].name} · ${GRADES[g].color}</h2><p>${MATERIALS[k].source} tại <b>${r.name}</b>.</p><p>${unlocked?'Đã mở khu vực.':r.unlockText}</p>${k==='stone'?'<p>Luyện từ 2 Thanh Thạch + 1 Linh khí cùng màu trong Nguyên liệu.</p><button id="sourceRefine">Mở luyện đá đúng màu</button>':`<button id="sourceAuto" ${!here||!unlocked?'disabled':''}>Auto ${MATERIALS[k].source} tại đây</button>`}<button id="sourceAtlas">Xem khu vực / đến cổng</button><button id="sourceBack">Quay lại công thức</button><p>Muốn đổi khu vực: đến cổng, chuyển map rồi bật thu thập. Nguyên liệu cũng ghép từ màu thấp theo 10:1.</p>`,'material-source');$('#sourceRefine')?.addEventListener('click',()=>{ui.grade=g;showPanel('materials');});$('#sourceAuto')?.addEventListener('click',()=>{closeModal();s.gatherGrade=g;if(mode==='farm')game.farmType='wolf';if(game.mode!==mode)game.setMode(mode);save();hud();});$('#sourceAtlas').onclick=()=>showPanel('atlas');$('#sourceBack').onclick=()=>showPanel(which);});
 return true;
}
